-- 省钱攻略补充：新增 38 条真实有用的省钱经验，覆盖外卖团购 / 电商购物 / 出行旅行 / 会员订阅 / 支付立减 / 学生专属 六类

INSERT INTO guides (id, title, content, category, tone, status, created_at) VALUES
-- ===== 外卖与团购省钱 =====
('guide-014','外卖先比价再下单','同一家店在美团、饿了么两个平台的价格和可用券常常不一样，下单前两个 App 都扫一眼，选到手价更低、能凑到免配送费的那边。','外卖与团购省钱','normal','approved','2026-10-22T12:00:00.000Z'),
('guide-015','天天神券 + 红包叠加免配送','美团外卖「天天神券」、饿了么每日红包是官方常驻入口，每天免费领；下单时优先挑能用大额券、且刚好达到免配送费门槛的店，别为了用券硬凑单。','外卖与团购省钱','normal','approved','2026-10-22T12:01:00.000Z'),
('guide-016','到店团购比单点划算','出去吃饭先在大众点评、美团搜店名看团购/套餐，2-3 人套餐通常比单点便宜三成以上；结算前再对一下买单折扣和团购哪个更省。','外卖与团购省钱','normal','approved','2026-10-22T12:02:00.000Z'),
('guide-017','代下单（麦当劳/瑞幸/星巴克）','淘宝或闲鱼搜「麦当劳代下单」「瑞幸代下单」等，常有 5-8 折；但属第三方渠道，下单前看清评价、尽量选可当场取餐再确认的，避免先款被骗。','外卖与团购省钱','warn','approved','2026-10-22T12:03:00.000Z'),
('guide-018','霸王餐 / 免费试 / 试吃官','大众点评「免费试」、美团「试吃官」、歪麦霸王餐、小蚕荟等都有免费或低价试吃名额，报名中签即可白嫖一顿；注意看清是否需要写评价、有无额外收费。','外卖与团购省钱','normal','approved','2026-10-22T12:04:00.000Z'),
('guide-019','瑞幸 9.9 与星巴克立减','瑞幸经常有 9.9 元券，先领券再下单比原价便宜一大半；星巴克用银行立减金、会员日或自带杯减钱，别直接原价点单。','外卖与团购省钱','normal','approved','2026-10-22T12:05:00.000Z'),
('guide-020','自助餐挑午市','同品牌自助餐午市普遍比晚市便宜 20%-40%，菜品差别不大；周末节假日贵、工作日午市最划算。','外卖与团购省钱','normal','approved','2026-10-22T12:06:00.000Z'),
('guide-021','自带杯 + 打包省配送','饮品自带杯在星巴克、瑞幸等都有减免；多人聚餐点得少不如打包回家，既省配送费又避免浪费。','外卖与团购省钱','normal','approved','2026-10-22T12:07:00.000Z'),

-- ===== 电商购物省钱 =====
('guide-022','1688 找源头工厂','买日用品、服饰、收纳等先上 1688 搜同款，认准「源头工厂」「实力商家」标签，价格常比淘宝零售便宜 30%-50%；大批量或需要贴牌时更明显。','电商购物省钱','normal','approved','2026-10-22T12:08:00.000Z'),
('guide-023','拼多多百亿补贴','大牌数码、家电、美妆在拼多多「百亿补贴」常是全网低价，认准「百亿补贴」「官方旗舰店」标识；价格异常低又无官方标识的要警惕。','电商购物省钱','normal','approved','2026-10-22T12:09:00.000Z'),
('guide-024','先加购再等大促看真实到手价','把想买的加购物车，双11/618 前后看「到手价」而非「划线原价」；很多商家先提价再打折，盯历史价格避免买在高点。','电商购物省钱','normal','approved','2026-10-22T12:10:00.000Z'),
('guide-025','领券 + 满减 + 返利叠加','下单前依次领店铺券、平台券、跨店满减，再通过返利类 App（如京粉、返利网）下单拿返利；几层叠加后往往能再省 10%-20%。','电商购物省钱','normal','approved','2026-10-22T12:11:00.000Z'),
('guide-026','比价工具看历史价格曲线','用「什么值得买」或浏览器比价插件看商品近 30/90 天的价格曲线，低于历史均价再入手，避免被「今日特价」误导。','电商购物省钱','normal','approved','2026-10-22T12:12:00.000Z'),
('guide-027','新人首单 / 学生专享价','很多平台对新人首单有超低价或大额券；学生认证后还能领专属券，同一件商品换个账号或认证身份常能更低。','电商购物省钱','normal','approved','2026-10-22T12:13:00.000Z'),
('guide-028','闲鱼淘「全新未拆」二手','别人冲动消费或送礼多出来的全新商品（数码、母婴、图书、家电）在闲鱼常 5-7 折；优先选同城面交、信用分高、支持验货的卖家，警惕先款和「全新但极低价」陷阱。','电商购物省钱','warn','approved','2026-10-22T12:14:00.000Z'),
('guide-029','大件用国补 + 以旧换新','买家电、数码留意政府补贴（国补）和「以旧换新」，叠加后空调冰箱、手机等能省几百到上千；先确认型号是否在补贴目录内。','电商购物省钱','normal','approved','2026-10-22T12:15:00.000Z'),

-- ===== 出行旅行省钱 =====
('guide-030','机票提前买 + 多平台比价','机票一般提前 2-4 周买更便宜，用携程、去哪儿、飞猪三家比价；避开周五晚、周日返程等高峰，早班或夜班机也更便宜。','出行旅行省钱','normal','approved','2026-10-22T12:16:00.000Z'),
('guide-031','低价日历 + 淡季出行','携程/去哪儿有「低价日历」能看哪天机票最便宜；错峰、淡季出行，酒店机票加起来能省 30%-50%，体验还更好。','出行旅行省钱','normal','approved','2026-10-22T12:17:00.000Z'),
('guide-032','火车票候补 / 中转 / 夜班','抢不到直达就点候补，或买中转车票；硬卧、硬座比高铁便宜很多，夜间卧铺还能省一晚酒店钱。','出行旅行省钱','normal','approved','2026-10-22T12:18:00.000Z'),
('guide-033','酒店多平台比价 + 返现','同一家酒店在携程、美团、飞猪、同程价格可能差几十到上百；下单前多平台比价，再叠加会员价、平台返现或信用卡立减。','出行旅行省钱','normal','approved','2026-10-22T12:19:00.000Z'),
('guide-034','顺风车 / 公共交通替代打车','长途出行用顺风车、拼车比快车便宜近一半；市内优先地铁、公交，打车选拼车或一口价更划算。','出行旅行省钱','normal','approved','2026-10-22T12:20:00.000Z'),
('guide-035','积分兑机票 / 住宿 / 接送机','航司里程、酒店积分、信用卡积分平时别闲置，可兑换免费机票、酒店住宿、接送机、贵宾厅，是长期积累的「隐形返现」。','出行旅行省钱','normal','approved','2026-10-22T12:21:00.000Z'),

-- ===== 会员与订阅省钱 =====
('guide-036','联合会员一份钱多份权益','京东 PLUS+腾讯视频、淘宝 88VIP、饿了么会员等「联合会员」把多项权益打包，比分开买便宜一半以上；先看自己常用哪几家再决定。','会员与订阅省钱','normal','approved','2026-10-22T12:22:00.000Z'),
('guide-037','视频会员别连续订、可拼家庭版','只在追剧那个月开月卡，或用闲鱼买短期卡、和朋友拼家庭版分摊；爱奇艺、腾讯、优酷都有家庭/多端版，人均更省。','会员与订阅省钱','normal','approved','2026-10-22T12:23:00.000Z'),
('guide-038','音乐 / 云盘家庭套餐分摊','QQ音乐、网易云、iCloud、百度网盘等家庭版可多人共用，人均成本通常比单人价低一半以上；注意家庭组成员有管理权限限制。','会员与订阅省钱','normal','approved','2026-10-22T12:24:00.000Z'),
('guide-039','免费试用后立刻关自动续费','很多 App 用「免费试用 7 天」诱导开通自动续费，试用完就扣钱；开通后立刻进支付设置关掉自动续费，试用到期自动停，不会多扣。','会员与订阅省钱','normal','approved','2026-10-22T12:25:00.000Z'),
('guide-040','会员日 / 新人首月价','各平台会员日、新人首月价（如视频会员首月 6 元）常比年费更灵活；先低价体验一个月，用得频繁再考虑年卡。','会员与订阅省钱','normal','approved','2026-10-22T12:26:00.000Z'),

-- ===== 支付立减与信用卡 =====
('guide-041','每天领银行立减金','微信「摇优惠」、支付宝「银行卡天天抽奖」每天免费抽银行立减金（0.5-10 元），小额消费、缴费都能抵扣；养成每天顺手点一下的习惯。','支付立减与信用卡','normal','approved','2026-10-22T12:27:00.000Z'),
('guide-042','信用卡返现与积分','日常消费优先刷有返现、多倍积分的信用卡，积分兑立减金、里程或礼品；账单日前对好账，避免因为忘还产生利息和逾期。','支付立减与信用卡','normal','approved','2026-10-22T12:28:00.000Z'),
('guide-043','大额用免息分期','买大件时用花呗/白条/信用卡的「免息分期」，把现金留手边；但只选明确写「0 手续费、免息」的，有利息的分期一律不碰。','支付立减与信用卡','normal','approved','2026-10-22T12:29:00.000Z'),
('guide-044','支付后领「支付有礼」券','微信/支付宝支付完成后常有「支付有礼」入口，随手领下次可用的抵扣券，长期积累也是一笔省下来的钱。','支付立减与信用卡','normal','approved','2026-10-22T12:30:00.000Z'),
('guide-045','话费 / 水电缴费折扣','联通 App 官方充值约 96.5 折、电信每月 3 号充值 95 折；水电燃气用云闪付、支付宝缴费常有立减或随机减，别原价交。','支付立减与信用卡','normal','approved','2026-10-22T12:31:00.000Z'),

-- ===== 学生专属省钱 =====
('guide-046','学生认证领专属券','支付宝、京东、淘宝完成学生认证后，可领专属优惠券和会员学生价；同一商品学生价常比普通价低不少。','学生专属省钱','normal','approved','2026-10-22T12:32:00.000Z'),
('guide-047','海底捞学生 69 折','支付宝搜「海底捞学生优惠」完成学信网认证，每月领 4 张券（69折2张+88折2张）；69 折限工作日 14:00-17:00、22:00 后，一桌限用 1 张。','学生专属省钱','normal','approved','2026-10-22T12:33:00.000Z'),
('guide-048','苹果教育优惠','全日制学生、教职工用教育优惠买 Mac/iPad 直降 800 元起，活动期还送耳机；官网、天猫、京东均可学信网或录取通知书认证。','学生专属省钱','normal','approved','2026-10-22T12:34:00.000Z'),
('guide-049','GitHub 学生包','在校生用学校邮箱或学生证认证 GitHub Student Pack，可领多家云厂商赠金、免费域名、IDE、AI 工具等多项权益，每年续认证即可。','学生专属省钱','normal','approved','2026-10-22T12:35:00.000Z'),
('guide-050','视频会员学生价','爱奇艺学生年卡约 99 元，腾讯、优酷、芒果学生月卡 10-15 元，QQ音乐绿钻首月 5 元；在各 App 会员页找「学生特惠」认证购买。','学生专属省钱','normal','approved','2026-10-22T12:36:00.000Z'),
('guide-051','景区 / 电影 / 交通学生票','景点门票、电影票、部分火车和长途汽车凭学生证可享半价或优惠；出门随身带学生证（或电子学籍认证），能省下不少。','学生专属省钱','normal','approved','2026-10-22T12:37:00.000Z');
